import sys
import os

def load_store():
    if os.path.exists('store.dat'):
        with open('store.dat', 'r') as f:
            store = {}
            for line in f:
                if line.strip():
                    key, value = line.strip().split('=', 1)
                    store[key] = value
            return store
    return {}

def save_store(store):
    with open('store.dat', 'w') as f:
        for key in sorted(store.keys()):
            f.write(f"{key}={store[key]}\n")

def main():
    store = load_store()
    while True:
        line = sys.stdin.readline().strip()
        if not line:
            continue
        if line == 'quit':
            save_store(store)
            sys.exit(0)
        tokens = line.split()
        if not tokens:
            continue
        cmd = tokens[0]
        if cmd == 'set' and len(tokens) == 3:
            key, value = tokens[1], tokens[2]
            store[key] = value
            print("OK")
        elif cmd == 'get' and len(tokens) == 2:
            key = tokens[1]
            if key in store:
                print(store[key])
            else:
                print("KEY_NOT_FOUND")
        elif cmd == 'delete' and len(tokens) == 2:
            key = tokens[1]
            if key in store:
                del store[key]
                print("OK")
            else:
                print("KEY_NOT_FOUND")
        elif cmd == 'list':
            for key in sorted(store.keys()):
                print(f"{key}={store[key]}")
        else:
            print("Invalid command")

if __name__ == "__main__":
    main()
